private void renderTrail(VertexConsumer buffer, AraTrailParticle particle, Camera camera, float partialTicks) {
        particle.updateDynamicData(partialTicks);
        clearMeshData();

        var points = particle.getPoints();

        // We need at least two points to create a trail mesh.
        if (points.size() > 1) {
            var worldToTrail = particle.getWorldToTrail();
            Vector3f localCamPosition = worldToTrail.transformPosition(camera.getPosition().toVector3f());

            renderAgedSpans(particle, worldToTrail, partialTicks,
                    (start, end) -> updateSegmentMesh(particle, start, end, localCamPosition));

            // safe after the state restore: reads only the mesh lists, worldToTrail and the camera
            renderMesh(particle, buffer, camera);
        }
    }

public void updateDynamicData(float partialTicks) {
        var transform = getTransform();
        this.worldPosition = worldPositionSupplier == null ? transform.position() : worldPositionSupplier.get(partialTicks);
        this.worldForward = worldForwardSupplier == null ? transform.forward() : worldForwardSupplier.get(partialTicks);
        this.worldUp = worldUpSupplier == null ? transform.up() : worldUpSupplier.get(partialTicks);
        this.worldRight = worldRightSupplier == null ? transform.right() : worldRightSupplier.get(partialTicks);
        this.colorMultiplier = colorMultiplierSupplier == null ? new Vector4f(1) : colorMultiplierSupplier.get(partialTicks);
        this.thicknessMultiplier = thicknessMultiplierSupplier == null ? 1 : thicknessMultiplierSupplier.get(partialTicks);
        this.lifeTime = lifetimeSupplier == null ? runtime.time.get() : lifetimeSupplier.get();
    }

public void extrapolatePhysics(float ticks) {
        var gravity = getTrailGravity();
        float damping = runtime.physics.damping.get();
        var velocity = new Vector3f();
        for (Point point : points) {
            velocity.set(point.velocity);
            for (float owed = ticks; owed > 1e-6f; owed -= 1f) {
                integrate(point.position, velocity, gravity, damping, Math.min(owed, 1f) / 20f);
            }
        }
    }

private static void integrate(Vector3f position, Vector3f velocity, Vector3f gravity, float damping, float timestep) {
        velocity.fma(timestep, gravity).mul((float) Math.pow(1 - Mth.clamp(damping, 0, 1), timestep));
        position.fma(timestep, velocity);
    }

private Vector3f getTrailGravity() {
        var gravity = new Vector3f(runtime.physics.gravity.get());
        var space = runtime.physics.gravitySpace.get();
        if (space == ValueSpace.Local) {
            getTransform().localToWorldMatrix().transformDirection(gravity);
        } else if (space == ValueSpace.Custom) {
            CustomSpace.dirToWorld(config.physicsSetting.gravityCustomSpace, emitter.getScene(), gravity);
        }
        return getWorldToTrail().transformDirection(gravity);
    }

private void updatePointsLifecycle(float deltaTime) {
        for (int i = points.size() - 1; i >= 0; --i)
        {

            var point = points.get(i);
            point.life -= deltaTime;

            if (point.life <= 0)
            {

                // Unsmoothed trails: wait until the next (newer) point is also dead, so the render-time tail
                // retract can shrink this segment to zero (f reaches 1 only when next.life hits 0) before
                // removal. Removing at life<=0 would pop a whole segment when the emission interval > 1 tick.
                if (config.smoothness <= 1)
                {
                    if (points.get(Math.min(i + 1, points.size() - 1)).life <= 0)
                        points.removeAt(i);
                }
                // Smoothed trails however, should wait until the next 2 points are dead too. This ensures spline continuity.
                else
                {
                    if (points.get(Math.min(i + 1, points.size() - 1)).life <= 0 &&
                            points.get(Math.min(i + 2, points.size() - 1)).life <= 0)
                        points.removeAt(i);
                }

            }
        }
    }

