private int collectRenderPoints(TrailParticle particle, Vector3f cameraPos, float partialTicks) {
        var tails = particle.getTails();
        var rawTails = particle.getRawTails();
        var color = particle.getRealColor(partialTicks);
        scratchLight = particle.getRealLight(partialTicks);

        Vector3f headPos = particle.getHeadPosition(partialTicks);
        int tailSize = tails.size();
        boolean pushHead = true;
        if (tailSize > 0) {
            Vector3f lastPos = tails.getPosition(tailSize - 1);
            if (lastPos.equals(headPos)) {
                pushHead = false;
            }
        }
        // logical point list = tails plus (optionally) the head; n mirrors the CPU strip's size
        int n = tailSize + (pushHead ? 1 : 0);
        if (n < 2) return 0;

        var lerpDur = 0f;
        var t = 0f;
        if (rawTails.size() > 1) {
            lerpDur = rawTails.getLifeTime(1) - rawTails.getLifeTime(0);
            t = 1 - (rawTails.getLifeTime(0) + 1 - partialTicks) / lerpDur;
        }

        // first rendered segment k — the skipped segments form a prefix (lifetimes grow with index)
        int k = -1;
        boolean lerpFirst = false;
        float lerpFactor = 0;
        for (int i = 0; i < n - 1; i++) {
            float lifeI = (pushHead && i == n - 1) ? 100 : tails.getLifeTime(i);
            float lifeI1 = (pushHead && i + 1 == n - 1) ? 100 : tails.getLifeTime(i + 1);
            if (lifeI - partialTicks < 0f && lifeI1 - partialTicks < 0) continue;
            var currT = lifeI / lerpDur;
            var nextT = lifeI1 / lerpDur;
            if (nextT < t) continue;
            k = i;
            if (lerpDur > 0 && currT <= t && t <= nextT) {
                lerpFirst = true;
                lerpFactor = (t - currT) / (nextT - currT);
            }
            break;
        }
        if (k == -1) return 0;

        int count = n - k;
        ensureScratch(count);
        float lifetime = Math.max(particle.getLifetimeSupplier().get(), 1.0E-5f);
        float uLast = 0;

        for (int j = k; j < n; j++) {
            int idx = j - k;
            boolean isPushedHead = pushHead && j == n - 1;

            Vector3f pos = isPushedHead ? headPos : tails.getPosition(j);
            if (j == k && lerpFirst) {
                Vector3f next = (pushHead && j + 1 == n - 1) ? headPos : tails.getPosition(j + 1);
                pos = new Vector3f(pos).lerp(next, lerpFactor);
            }
            px[idx] = pos.x - cameraPos.x;
            py[idx] = pos.y - cameraPos.y;
            pz[idx] = pos.z - cameraPos.z;

            // the pushed head reuses the OLDEST tail's color/width (CPU quirk — keep it)
            float tcr, tcg, tcb, tca, tw;
            if (isPushedHead) {
                if (tailSize > 0) {
                    var headColor = tails.getColor(0);
                    tcr = headColor.x();
                    tcg = headColor.y();
                    tcb = headColor.z();
                    tca = headColor.w();
                    tw = tails.getWidth(0);
                } else {
                    tcr = tcg = tcb = tca = 1;
                    tw = 0;
                }
            } else {
                var tailColor = tails.getColor(j);
                tcr = tailColor.x();
                tcg = tailColor.y();
                tcb = tailColor.z();
                tca = tailColor.w();
                tw = tails.getWidth(j);
            }
            cr[idx] = color.x() * tcr;
            cg[idx] = color.y() * tcg;
            cb[idx] = color.z() * tcb;
            ca[idx] = color.w() * tca;
            width[idx] = tw;

            // per-point u: segment j's u0; the head point continues with the last segment's u1
            if (j <= n - 2) {
                var uvs = particle.getUVs(j, n, partialTicks);
                u[idx] = uvs.x();
                if (j == k) {
                    scratchV0 = uvs.y();
                    scratchV1 = uvs.w();
                }
                if (j == n - 2) {
                    uLast = uvs.z();
                }
            } else {
                u[idx] = uLast;
            }

            // per-point channels
            pointT[idx] = j / (n - 1f);
            float life = isPushedHead ? 100 : tails.getLifeTime(j);
            pointLife[idx] = 1 - Math.min(Math.max(life / lifetime, 0f), 1f);
        }
        return count;
    }

private void emissionStep(float time) {
        // Acumulate the amount of time passed:
        accumTime += time;

        // If enough time has passed since the last emission (>= timeInterval), consider emitting new points.
        if (accumTime >= runtime.timeInterval.get()) {
            if (config.emit) {
                var position = getWorldToTrail().transformPosition(getWorldPosition());

                // If there's less than 2 points, or if the last 2 points are too far apart, spawn a new one:
                if (points.isEmpty() || (
                        position.distance(points.getLast().position) >= runtime.minDistance.get()
                )) {
                    emitPoint(position);
                    accumTime = 0;
                }
            }
        }
    }

@Override
public void doRender(EntityPredatorArrowGuide entity, double x, double y, double z, float entityYaw, float partialTicks) {
	super.doRender(entity, x, y, z, entityYaw, partialTicks);

	Entity target = entity.getTarget();
	Entity ridingEntity = entity.getRidingEntity();

	if(target != null) {
		double ix = entity.lastTickPosX + (entity.posX - entity.lastTickPosX) * partialTicks;
		double iy = entity.lastTickPosY + (entity.posY - entity.lastTickPosY) * partialTicks;
		double iz = entity.lastTickPosZ + (entity.posZ - entity.lastTickPosZ) * partialTicks;

		double targetIx = target.lastTickPosX + (target.posX - target.lastTickPosX) * partialTicks;
		double targetIy = target.lastTickPosY + (target.posY - target.lastTickPosY) * partialTicks + target.getEyeHeight();
		double targetIz = target.lastTickPosZ + (target.posZ - target.lastTickPosZ) * partialTicks;

		double diffX = targetIx - ix;
		double diffY = targetIy - iy;
		double diffZ = targetIz - iz;

		LightingUtil.INSTANCE.setLighting(255);

		GlStateManager.disableLighting();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0);
		GlStateManager.disableCull();
		GlStateManager.depthMask(false);

		this.bindTexture(BEAM_TEXTURE);

		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y - (ridingEntity != null ? (entity.posY - ridingEntity.posY) : 0), z);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder buffer = tessellator.getBuffer();

		buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);

		ParticleBeam.buildBeam(diffX, diffY, diffZ, new Vec3d(-diffX, -diffY, -diffZ), 0.05F, 0, 2F,
				ActiveRenderInfo.getRotationX(), ActiveRenderInfo.getRotationZ(), ActiveRenderInfo.getRotationYZ(), ActiveRenderInfo.getRotationXY(), ActiveRenderInfo.getRotationXZ(),
				(vx, vy, vz, u, v) -> {
					buffer.pos(vx, vy, vz).tex(u, v).color(35, 80, 110, 255).endVertex();
				});

		tessellator.draw();

		GlStateManager.popMatrix();

		GlStateManager.depthMask(true);
		GlStateManager.enableCull();
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
		GlStateManager.disableBlend();
		GlStateManager.enableLighting();

		LightingUtil.INSTANCE.revert();
	}
}
